"use server";

import { auth } from "@/auth";
import { readSendingActive } from "@/lib/sending-status";

export async function getSendingActive() {
  const session = await auth();
  // A background poll must not navigate away from a pending deletion's
  // confirmation and delayed sign-out when its session becomes unavailable.
  if (!session?.user?.id) throw new Error("Unauthenticated");
  return readSendingActive(session.user.id);
}
